using System.ComponentModel; using System.Diagnostics; using Archy.SharedKernel.Primitives;
namespace Archy.Features.Analysis.MineGitCoChanges;
/// <summary>Mines bounded local Git history with argument lists only; emitted edges represent temporal coupling, never semantic dependencies.</summary>
public sealed class GitCoChangeMiner : IGitCoChangeMiner
{
 public async ValueTask<Result<IReadOnlyList<CoChangeEdge>>> MineAsync(CoChangeMiningRequest request,CancellationToken cancellationToken){ArgumentNullException.ThrowIfNull(request);if(string.IsNullOrWhiteSpace(request.RepositoryRoot)||request.MaximumCommits is<1 or>5000||request.MinimumCoChanges is<1 or>1000)return ResultFactory.Failure<IReadOnlyList<CoChangeEdge>>(Problem.Validation("Co-change mining requires bounded local Git history settings."));try{using var p=new Process{StartInfo=new ProcessStartInfo("git"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true,WorkingDirectory=request.RepositoryRoot}};p.StartInfo.ArgumentList.Add("log");p.StartInfo.ArgumentList.Add($"--max-count={request.MaximumCommits}");p.StartInfo.ArgumentList.Add("--pretty=format:---ARCHY-COMMIT---");p.StartInfo.ArgumentList.Add("--name-only");if(!p.Start())return ResultFactory.Failure<IReadOnlyList<CoChangeEdge>>(Problem.Storage("Archy could not start Git co-change mining."));var output=p.StandardOutput.ReadToEndAsync(cancellationToken);var error=p.StandardError.ReadToEndAsync(cancellationToken);await p.WaitForExitAsync(cancellationToken);if(p.ExitCode!=0)return ResultFactory.Failure<IReadOnlyList<CoChangeEdge>>(Problem.Storage($"Git co-change mining failed: {(await error).Trim().Take(256)}"));var counts=new Dictionary<(string,string),int>();foreach(var commit in (await output).Split("---ARCHY-COMMIT---",StringSplitOptions.RemoveEmptyEntries)){var paths=commit.Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries).Where(IsPath).Distinct(StringComparer.Ordinal).OrderBy(x=>x,StringComparer.Ordinal).ToArray();for(var i=0;i<paths.Length-1;i++)for(var j=i+1;j<paths.Length;j++){var key=(paths[i],paths[j]);counts[key]=counts.TryGetValue(key,out var count)?count+1:1;}}return ResultFactory.Success<IReadOnlyList<CoChangeEdge>>([..counts.Where(x=>x.Value>=request.MinimumCoChanges).Select(x=>new CoChangeEdge(x.Key.Item1,x.Key.Item2,x.Value,Math.Round(x.Value/(double)request.MaximumCommits,6))).OrderByDescending(x=>x.Score).ThenBy(x=>x.LeftRepositoryRelativePath,StringComparer.Ordinal).ThenBy(x=>x.RightRepositoryRelativePath,StringComparer.Ordinal)]);}catch(Win32Exception){return ResultFactory.Failure<IReadOnlyList<CoChangeEdge>>(Problem.Storage("Git is unavailable for co-change mining."));}catch(Exception e)when(e is IOException or UnauthorizedAccessException){return ResultFactory.Failure<IReadOnlyList<CoChangeEdge>>(Problem.Storage($"Archy could not mine Git co-changes: {e.Message}"));}}
 private static bool IsPath(string value)=>value.Length>0&&!value.StartsWith("fatal:",StringComparison.OrdinalIgnoreCase)&&!Path.IsPathRooted(value)&&!value.Contains("..",StringComparison.Ordinal);
}
